INSERT INTO public.products (product_id, name, brand, description, price, sizes, image_url, stock_quantity, category, colors_general) VALUES
('KVP004', 'Baskets Adidas Homme Montreal RM Collegiate Green', ' Adidas', 'Découvrez l''alliance parfaite entre héritage sportif et modernité avec ces baskets signées par la marque Adidas. Conçues pour les hommes exigeants, elles se distinguent par leur élégance intemporelle et leur qualité supérieure. Leur dessus en cuir offre une allure raffinée, tandis que la doublure synthétique assure un confort optimal tout au long de la journée. La semelle extérieure en caoutchouc garantit une durabilité exceptionnelle et une adhérence fiable sur toutes les surfaces. Les célèbres 3-Stripes sur les côtés et le logo Trefoil sur la languette et le talon soulignent le caractère authentique de la marque. Un marquage en feuille d''or ajoute une touche de sophistication discrète. Inspirées d''un modèle iconique des années 70, ces baskets incarnent un équilibre idéal entre fonctionnalité et style. Leur fermeture à lacets permet un ajustement précis, répondant ainsi aux attentes des amateurs de mode et de confort. Parfaites pour compléter une garde-robe masculine, elles séduisent par leur couleur distinctive Collegiate Green / Cloud White / Core Black. Optez pour une paire qui traverse les tendances et affirmez votre passion pour la mode et la performance avec ce modèle incontournable d''Adidas.', '110', '["40 2/3", "41 1/3", "42 2/3", "43 1/3", "44 2/3", "45 1/3", "46 2/3", "40", "42", "44", "46"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_men_montreal_rm_collegiate_green_cloud_white_core_black_6.jpg', '24', 'Homme', '[''vert'', ''noir'', ''blanc'']'),
('KVP005', 'Baskets Adidas Femme Handball Spezial Lucid Blue', ' Adidas', 'Découvrez l''élégance intemporelle associée au confort moderne avec cette paire de baskets signée par la marque Adidas. Inspirée du style rétro des années 70, cette création séduit par sa silhouette iconique et ses détails raffinés, dont les fameuses 3-Stripes et le marquage doré sur le côté. La matière en cuir véritable assure une allure sophistiquée et une durabilité optimale, tandis que la doublure textile offre un bien-être incomparable au quotidien. Sa semelle extérieure en caoutchouc garantit une excellente adhérence et une grande résistance à l''usure, idéale pour accompagner chaque pas avec style. La combinaison de couleurs vives – bleu, rose et une touche de lime – apporte une note dynamique et unique à toutes vos tenues, faisant de ce modèle un incontournable pour les amateurs de mode vintage. Conçue à l''origine pour la performance sur le terrain de handball, cette basket s''est imposée comme un classique incontournable dans l''univers du streetwear. Convenant aux femmes, elle allie parfaitement héritage sportif et tendance contemporaine. Adoptez un modèle emblématique qui enrichira votre collection et affirmez votre goût pour l''authenticité et la qualité d''Adidas.', '110', '["36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "41 1/3", "36", "38", "40", "42"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_women_handball_spezial_lucid_blue_lime_burst_lucid_pink_6.jpg', '0', 'Femme', '[''rose'', ''bleu'']'),
('KVP006', 'Baskets Adidas Femme Handball Spezial Lucid Pink', ' Adidas', 'Découvrez l''alliance parfaite entre héritage sportif et style contemporain avec ces baskets signées Adidas. Issues d''un design iconique des années 70, revisité avec une touche des années 90, elles séduisent par leur silhouette rétro et leurs couleurs vibrantes : Lucid Pink, Collegiate Purple et Almost Yellow. La matière supérieure en cuir offre une allure premium et assure une durabilité remarquable, tandis que la doublure textile garantit un confort optimal au quotidien. La semelle extérieure en caoutchouc procure une adhérence flexible, idéale pour accompagner chaque mouvement. Les fameuses 3-Stripes et le détail doré sur le côté soulignent le caractère intemporel de ce modèle, symbole de la marque légendaire Adidas. Grâce à une fermeture à lacets ajustable, ces baskets s''adaptent parfaitement à la morphologie du pied. Conçues pour les femmes qui apprécient la qualité, l''authenticité et la mode urbaine, elles constituent un choix incontournable pour enrichir toute collection de chaussures. Adoptez un look casual et sophistiqué, tout en bénéficiant du savoir-faire reconnu d''Adidas, leader mondial du sport et du lifestyle.', '110', '["36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "41 1/3", "36", "38", "40", "42"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_women_handball_spezial_lucid_pink_collegiate_purple_almost_yellow_7.jpg', '13', 'Femme', '[''rose'', ''violet'', ''jaune'']');